// G112: the text of the two generated files. listargsTable.ts holds only the names (it is in the start chunk, via
// listargs.ts); listargsEvidence.ts holds each name's reason and the skipped names, read by listargsTable.test.ts only,
// so the evidence (25 kB) stays out of the app bundle. G124: the hits with a documented list form (intended.ts) leave the
// refused names for PROBED_LIST_FORMS, with their evidence in PROBED_LIST_FORM_EVIDENCE.
import type { ListForm } from "./intended.ts";

const HEAD = `// SPDX-License-Identifier: GPL-3.0-or-later
// GENERATED by tools/probes/list-args.ts (WRITE=1) on the pinned engine; do not edit by hand. listargsTable.test.ts fails when
// the engine and this table disagree. G112 (backlog F103): the names of Find's index and of the census whose one list argument
// Giac reads as their argument list (f(list[a,b]) = f(a,b), or one number)`;

/** The texts of app/src/engine/listargsTable.ts and app/src/engine/listargsEvidence.ts. */
export function tableFiles(
  hits: readonly (readonly [string, string])[],
  forms: readonly (readonly [string, ListForm, string])[],
  skip: readonly (readonly [string, string])[],
  deadline: number,
  count: number,
): { table: string; evidence: string } {
  const q = (s: string): string => JSON.stringify(s);
  const lines: string[] = [];
  let cur = " ";
  const formed = new Set(forms.map(([n]) => n));
  for (const [n] of hits) {
    if (formed.has(n)) continue;
    const item = ` ${q(n)},`;
    if (cur.length + item.length > 120) {
      lines.push(cur);
      cur = " ";
    }
    cur += item;
  }
  if (cur.trim()) lines.push(cur);
  const table = `${HEAD}; each name's reason is in listargsEvidence.ts
// (kept out of the app bundle).

/** The names, in the probe's order, but those of PROBED_LIST_FORMS. */
export const PROBED_LIST_AS_ARGUMENTS: readonly string[] = [
${lines.join("\n")}
];

/** G124 (backlog F107): the names whose one list Giac reads as their arguments by documented intent, with the list's form
 *  ("any"; "integers", dimensions: exactly two integers of at least 1; "rows", a matrix's rows); outside the form the call stays refused. */
export const PROBED_LIST_FORMS: Readonly<Record<string, "any" | "integers" | "rows">> = {
${forms.map(([n, f]) => `  ${n}: ${q(f)},`).join("\n")}
};

/** How many names the probe asked (the index's and the census's, the skipped ones included). */
export const PROBED_NAMES = ${count};
`;
  const evidence = `${HEAD}: each name's reason. Read by listargsTable.test.ts only.

/** Name → the probe's evidence (the first sample that showed it). */
export const PROBED_EVIDENCE: Readonly<Record<string, string>> = {
${hits.map(([n, why]) => `  ${n}: ${q(why)},`).join("\n")}
};

/** G124: the evidence of each name of PROBED_LIST_FORMS (tools/probes/listargs/intended.ts): Giac's help or source, the value. */
export const PROBED_LIST_FORM_EVIDENCE: Readonly<Record<string, string>> = {
${forms.map(([n, , why]) => `  ${n}: ${q(why)},`).join("\n")}
};

/** Names the probe skipped: no answer in ${deadline} ms, or the engine threw (the test replays the rest in this order). */
export const PROBE_SKIPPED: Readonly<Record<string, string>> = {
${skip.map(([n, why]) => `  ${n}: ${q(why)},`).join("\n")}
};
`;
  return { table, evidence };
}
